const edgeHelpers = `\nasync function hiddenHomeworkIds(studentId:string){const {data,error}=await db.from("foresta_v3_homework_overrides").select("homework_id").eq("student_id",studentId).eq("hidden",true);if(error)throw error;return new Set((data||[]).map(row=>String(row.homework_id||"")))}\n\nasync function adjustHomework(profile:Record<string,unknown>,body:Record<string,unknown>){\n if(profile.role!=="teacher")throw new Error("FORBIDDEN");const studentId=String(body.studentId||""),subject=normalize(body.subject);assertStudentAccess(profile,studentId);if(!studentId||!subject)throw new Error("INVALID_ACTION");\n const dash=await snapshot(studentId,"getStudentDashboard");if(!dash)throw new Error("SNAPSHOT_NOT_READY");if(!campusMatches(profile.campus,dash.payload?.student?.campus))throw new Error("FORBIDDEN");\n const base=(dash.payload?.homework||[]).filter((item:Record<string,unknown>)=>!item.archived&&normalize(item.subject)===subject&&String(item.source||"")==="teacher");const allowed=new Set(base.map((item:Record<string,unknown>)=>String(item.homeworkId||"")));\n const candidate=[...new Set((Array.isArray(body.homeworkIds)?body.homeworkIds:[]).map(String).filter(Boolean))],keep=new Set((Array.isArray(body.keepHomeworkIds)?body.keepHomeworkIds:[]).map(String).filter(Boolean));if(candidate.some(id=>!allowed.has(id))||[...keep].some(id=>!allowed.has(id)))throw new Error("FORBIDDEN");\n const removed=candidate.filter(id=>!keep.has(id)),now=new Date().toISOString();if(removed.length){const rows=removed.map(homework_id=>({homework_id,student_id:studentId,subject,hidden:true,actor_id:String(profile.loginId||""),updated_at:now}));const {error}=await db.from("foresta_v3_homework_overrides").upsert(rows,{onConflict:"homework_id"});if(error)throw error}\n if(keep.size){const {error}=await db.from("foresta_v3_homework_overrides").delete().in("homework_id",[...keep]).eq("student_id",studentId);if(error)throw error}\n return {ok:true,saved:true,studentId,subject,hiddenCount:removed.length,_v3:true};\n}\n`;
