const migration = `-- Make homework archive/restore immediately visible in the V3 read model and\n-- persist teacher next-homework visibility adjustments independently of GAS snapshots.\ncreate table if not exists public.foresta_v3_homework_overrides (\n  homework_id text primary key,\n  student_id text not null,\n  subject text not null default '',\n  hidden boolean not null default false,\n  actor_id text not null default '',\n  updated_at timestamptz not null default now()\n);\ncreate index if not exists foresta_v3_homework_overrides_student on public.foresta_v3_homework_overrides(student_id,subject,hidden);\nalter table public.foresta_v3_homework_overrides enable row level security;\nrevoke all on table public.foresta_v3_homework_overrides from anon, authenticated;\ngrant select,insert,update,delete on table public.foresta_v3_homework_overrides to service_role;\n\ncreate or replace function public.foresta_v3_enqueue_homework_snapshot_mutation(\n  p_mutation_id uuid, p_action text, p_student_id text, p_payload jsonb, p_homework_ids text[]\n) returns jsonb\nlanguage plpgsql security definer set search_path=public as $$\ndeclare\n  dash jsonb; arch jsonb; active jsonb; archived jsonb; moved jsonb := '[]'::jsonb;\n  existing boolean; requested_count integer; found_count integer;\nbegin\n  select exists(select 1 from foresta_v3_mutations where mutation_id=p_mutation_id) into existing;\n  if existing then return jsonb_build_object('duplicate',true); end if;\n  if p_action not in ('archiveHomework','restoreHomework','deleteHomework') or coalesce(array_length(p_homework_ids,1),0)=0 then raise exception 'INVALID_ACTION'; end if;\n  requested_count:=array_length(p_homework_ids,1);\n  select payload into dash from foresta_v3_snapshots where student_id=p_student_id and view='getStudentDashboard' and subject='' for update;\n  if dash is null then raise exception 'SNAPSHOT_NOT_READY'; end if;\n  insert into foresta_v3_snapshots(student_id,view,subject,payload,source_updated_at,updated_at)\n  values(p_student_id,'getHomeworkArchive','',jsonb_build_object('student',dash->'student','homework','[]'::jsonb,'canDelete',true),now(),now())\n  on conflict(student_id,view,subject) do nothing;\n  select payload into arch from foresta_v3_snapshots where student_id=p_student_id and view='getHomeworkArchive' and subject='' for update;\n  active:=coalesce(dash->'homework','[]'::jsonb); archived:=coalesce(arch->'homework','[]'::jsonb);\n  if p_action='archiveHomework' then\n    select count(*),coalesce(jsonb_agg(elem || '{\"archived\":true,\"canArchive\":false}'::jsonb),'[]'::jsonb) into found_count,moved from jsonb_array_elements(active) elem where elem->>'homeworkId'=any(p_homework_ids) and coalesce((elem->>'completed')::boolean,false);\n    if found_count<>requested_count then raise exception 'HOMEWORK_NOT_COMPLETE'; end if;\n    select coalesce(jsonb_agg(elem),'[]'::jsonb) into active from jsonb_array_elements(active) elem where not(elem->>'homeworkId'=any(p_homework_ids));\n    archived:=moved||archived;\n  elsif p_action='restoreHomework' then\n    select count(*),coalesce(jsonb_agg(elem || '{\"archived\":false}'::jsonb),'[]'::jsonb) into found_count,moved from jsonb_array_elements(archived) elem where elem->>'homeworkId'=any(p_homework_ids);\n    if found_count<>requested_count then raise exception 'INVALID_ACTION'; end if;\n    select coalesce(jsonb_agg(elem),'[]'::jsonb) into archived from jsonb_array_elements(archived) elem where not(elem->>'homeworkId'=any(p_homework_ids));\n    active:=moved||active;\n  else\n    select count(*) into found_count from jsonb_array_elements(archived) elem where elem->>'homeworkId'=any(p_homework_ids);\n    if found_count<>requested_count then raise exception 'INVALID_ACTION'; end if;\n    select coalesce(jsonb_agg(elem),'[]'::jsonb) into archived from jsonb_array_elements(archived) elem where not(elem->>'homeworkId'=any(p_homework_ids));\n  end if;\n  update foresta_v3_snapshots set payload=jsonb_set(dash,'{homework}',active,true),updated_at=now() where student_id=p_student_id and view='getStudentDashboard' and subject='';\n  update foresta_v3_snapshots set payload=jsonb_set(arch,'{homework}',archived,true),updated_at=now() where student_id=p_student_id and view='getHomeworkArchive' and subject='';\n  delete from foresta_v3_homework_overrides where student_id=p_student_id and homework_id=any(p_homework_ids);\n  insert into foresta_v3_mutations(mutation_id,action,student_id,payload,status,created_at,updated_at) values(p_mutation_id,p_action,p_student_id,p_payload,'accepted',now(),now());\n  return jsonb_build_object('duplicate',false,'active_count',jsonb_array_length(active),'archive_count',jsonb_array_length(archived));\nend $$;\nrevoke all on function public.foresta_v3_enqueue_homework_snapshot_mutation(uuid,text,text,jsonb,text[]) from public,anon,authenticated;\ngrant execute on function public.foresta_v3_enqueue_homework_snapshot_mutation(uuid,text,text,jsonb,text[]) to service_role;\n`;
fs.writeFileSync('supabase/migrations/202608310006_homework_archive_read_model.sql', migration);

